<script lang="ts">
import {onMount} from 'svelte';import {exportFeedback} from './export-feedback';import Icon from './Icon.svelte';import {loadCalendar,achievementExport,type CalendarPreview} from './bridge';
let {profile,achievement,t,language,onclose}:{profile:string;achievement:string;t:(key:string)=>string;language:string;onclose:()=>void}=$props();
let dialog:HTMLDialogElement;let data=$state<CalendarPreview|null>(null);let failed=$state(false);let busy=$state(false);let result=$state('');
onMount(()=>{dialog.showModal();let current=true;loadCalendar(profile,achievement).then(value=>{if(current)data=value;}).catch(()=>{if(current)failed=true;});return()=>{current=false;dialog.close();};});
async function action(action:string){if(busy)return;busy=true;failed=false;try{const value=await achievementExport(profile,achievement,language,{action});result=exportFeedback(value,result);}catch{failed=true;}finally{busy=false;}}
</script>
<dialog class="calendar-dialog" bind:this={dialog} oncancel={e=>{e.preventDefault();if(!busy)onclose();}}><h2><Icon name="calendar_days"/>{t('Добавить в календарь')}</h2>{#if data}<div class="calendar-preview"><strong>Extranjería — Cita</strong><span>{new Intl.DateTimeFormat(language==='en'?'en-GB':language,{dateStyle:'long',timeZone:'UTC'}).format(new Date(data.date+'T12:00:00Z'))} · {data.time}</span><small class="muted">{t('Местное время офиса')}</small><span>{data.office}</span><span class="muted">{data.address}</span></div><div class="calendar-choices"><button disabled={busy} onclick={()=>void action('google')}><img src="/brands/google-calendar.png" width="22" height="22" alt=""/>Google Calendar</button><button disabled={busy} onclick={()=>void action('save_calendar')}><Icon name="download"/>{t('Сохранить .ics')}</button></div><p class="muted note">{t('Номер подтверждения не включается.')}</p>{:else if !failed}<p class="muted">{t('Загрузка…')}</p>{/if}
{#if result}<div class="calendar-result" role="status"><strong>{t(result==='calendar_saved'?'Файл события сохранён':'Форма Google Calendar открыта')}</strong><p class="muted">{t(result==='calendar_saved'?'Открыть файл в календаре и подтвердить добавление.':'Выбрать календарь и напоминание, затем нажать «Сохранить» в Google Calendar.')}</p>{#if result==='calendar_saved'}<button disabled={busy} onclick={()=>void action('open_calendar')}><Icon name="external"/>{t('Открыть в календаре')}</button>{/if}</div>{/if}
{#if failed}<p class="error" role="alert">{t('Не удалось подготовить событие. Проверить дату и время записи.')}</p>{/if}<div class="close-actions"><button disabled={busy} onclick={onclose}>{t('Закрыть')}</button></div></dialog>
<style>.calendar-dialog{width:min(540px,calc(100vw - 32px));padding:22px;background:var(--bg);color:var(--text);border:1px solid var(--strong);border-radius:12px;max-height:calc(100vh - 32px);overflow:auto}.calendar-dialog::backdrop{background:#0008}h2{display:flex;align-items:center;gap:10px;font-size:19px;margin:0 0 16px}.calendar-preview{background:var(--surface);border:1px solid var(--line);border-radius:7px;padding:14px;display:flex;flex-direction:column;gap:7px;overflow-wrap:anywhere}.calendar-preview strong{font-size:15px}.calendar-choices{display:flex;gap:10px;margin:14px 0}.note{font-size:12px}.close-actions{display:flex;justify-content:flex-end;margin-top:18px}.calendar-result{padding:12px;border:1px solid var(--line);border-radius:7px;background:var(--surface)}.calendar-result p{font-size:12px;margin:7px 0}.calendar-result button{margin-top:5px}</style>
